'use strict';
(function(){
 const I=window.PippoI18n;
 const V=window.PortoVehicles,E=window.PortoBuffo,$=id=>document.getElementById(id);
 let state=E.initialState(),selected=null,verb='look',activePuzzle=null,saveAvailable=true;
 let audioContext=null,walkTimer=null;
 const symbols={sun:'☀',moon:'☾',star:'★'};
 const propArt=['key','chest','score','organ','machine','rope','kite','redCloth','cloth','footprints','sizeSign','comb','fork','sun','moon','star','parcel1','parcel2','parcel3','boat','helicopter','sea','lighthouse','cloudMachine','red','yellow','blue','orange','purple','green'];
 function icon(name){const index=propArt.indexOf(name==='sorter'?'machine':name);if(index<0)throw new RangeError('Unknown prop: '+name);return window.PippoArt.sprite('assets/props.png',index,6,5,64,64);}
 function speak(text,speaker='Pippo',force=false){if(!window.__gameKit?.settings.getSnapshot().muted&&(state.voice||force))window.PippoSpeech.speak(I.t(text),I.settings.language,speaker);}
 function tone(key){if(!I.settings.sounds)return;try{const Constructor=window.AudioContext||window.webkitAudioContext;if(!Constructor)return;audioContext??=new Constructor();audioContext.resume();const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type='sine';oscillator.frequency.value={sun:330,moon:440,star:554}[key];gain.gain.setValueAtTime(.12,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.4);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start();oscillator.stop(audioContext.currentTime+.4);}catch(error){console.warn('Nota audio non disponibile:',error);}}
 function say(text,speaker='Pippo',character=0,choices=[]){I.text($('message'),text);I.text($('speaker'),speaker);$('portrait').className=character===0?'character pippo-sprite idle':'character char-'+character;$('dialogChoices').replaceChildren();choices.forEach(choice=>{const b=document.createElement('button');I.text(b,choice.text);b.onclick=choice.action;$('dialogChoices').append(b);});speak(text,speaker);}
 function persist(){try{localStorage.setItem('porto_buffo_v2',JSON.stringify(state));}catch(error){console.warn('Salvataggio non disponibile:',error);saveAvailable=false;}render();}
 try{const current=localStorage.getItem('porto_buffo_v2'),old=localStorage.getItem('porto_buffo_v1');if(current){const candidate=JSON.parse(current);if(E.validateState(candidate))state=E.migrateState(candidate);else console.warn('Salvataggio v2 non valido: nuova partita.');}else if(old){state=E.migrateState(JSON.parse(old));localStorage.setItem('porto_buffo_v2',JSON.stringify(state));}}catch(error){console.warn('Lettura salvataggio non disponibile:',error);saveAvailable=false;}
 function setVerb(next){verb=next;if(next!=='use')selected=null;const pippo=$('pippo');pippo.classList.remove('pose-talk','pose-inspect','pose-point');if(next!=='use')pippo.classList.add({look:'pose-inspect',talk:'pose-talk',take:'pose-point'}[next]);document.querySelectorAll('[data-verb]').forEach(b=>{b.classList.toggle('active',b.dataset.verb===verb);b.setAttribute('aria-pressed',String(b.dataset.verb===verb));});renderInventory();I.text($('actionText'),{look:'Guarda…',talk:'Parla con…',take:'Prendi…',use:'Usa…'}[verb]);}
 function walk(x){
  const pippo=$('pippo'),scene=$('scene').getBoundingClientRect(),position=pippo.getBoundingClientRect();
  const current=(position.left-scene.left)/scene.width*100,width=position.width/scene.width*100;
  const target=Math.max(0,Math.min(100-width,x-width/2));
  clearTimeout(walkTimer);
  if(Math.abs(target-current)<.3){pippo.style.left=target+'%';pippo.classList.remove('walking');return;}
  pippo.classList.toggle('facing-left',target<current);
  pippo.style.left=target+'%';pippo.classList.add('walking');
  walkTimer=setTimeout(()=>pippo.classList.remove('walking'),700);
 }
 $('pippo').addEventListener('transitionend',event=>{if(event.propertyName==='left')$('pippo').classList.remove('walking');});
 function handleResult(result){persist();if(result.puzzle){showPuzzle(result.puzzle);return;}if(result.done){selected=null;if($('stationDialog').open)$('stationDialog').close();if(result.delivery){showAdventure();animateVehicle();}if($('puzzleDialog').open)$('puzzleDialog').close();say(result.text,'Pippo',0,state.caseIndex<5?[{text:'Prepariamo il prossimo caso!',action:()=>showHub(true)}]:[{text:'Guarda la mia carriera',action:()=>showHub(true)}]);}else say(result.text);}
 function interact(p){walk(p.x+(p.char!==undefined?(p.x>50?-17:17):-10));if(state.completed.includes(state.caseIndex)){say('Caso risolto! Possiamo esplorare ancora o preparare la prossima avventura alla stazione.');return;}if(verb==='look'){handleResult(E.look(state,p.id));return;}if(verb==='take'){if(p.char!==undefined){say('Mettere una persona nel taschino sarebbe molto poco professionale.');return;}handleResult(E.take(state,p.id));return;}if(verb==='talk'){if(p.char===undefined){say(p.id==='organ'?'L’organetto risponde solo con le note. Provo a usarlo?':'Gli ho chiesto come sta. Non ha risposto. Forse dovrei parlare con una persona.');return;}talk(p);return;}if(selected){handleResult(E.use(state,selected,p.id));return;}const puzzles={organ:'melody',baron:state.caseIndex===3?'suspect':null,sorter:'parcels'};if(puzzles[p.id])showPuzzle(puzzles[p.id]);else say(p.id==='chest'?'Una serratura! Prima devo trovare qualcosa per aprirla.':p.id==='cloudMachine'?'Per questa macchina serve qualcosa che voli. Posso costruirlo con gli oggetti nelle tasche.':'Scegli un oggetto nelle tasche, poi tocca dove vuoi usarlo.');}
 function talk(p){const c=state.caseIndex,choices=[];const choice=(text,action)=>choices.push({text,action});let greeting='';
  if(c===0&&p.id==='berto'){greeting='«Io custodisco le chiavi. E le chiavi custodiscono i segreti. E i segreti… beh, loro non fanno i turni di notte.»';choice('Hai la chiave del baule?',()=>showPuzzle('riddle'));choice('Posso diventare custode dei biscotti?',()=>say('«Solo se non li mangi durante il turno. Il posto è rimasto vuoto per questo motivo.»','Berto',1));}
  else if(c===0){greeting='«Gino ha nascosto la mia ricetta! Senza, le ciambelle mi vengono con il buco… fuori.»';choice('Da dove comincio?',()=>say('«Il baule è qui, ma Berto al molo tiene la chiave. Gli piacciono gli indovinelli più delle ciambelle. E questo è grave.»','Ada',2));choice('Una ciambella quadrata è un biscotto?',()=>say('«Domanda pericolosa, agente. Il sindacato dei biscotti potrebbe offendersi.»','Ada',2));}
  else if(c===1){greeting=p.id==='berto'?'«Nino suona sempre tre note. Purtroppo nell’ordine sbagliato. Le mie orecchie chiedono ferie.»':'«Nino ha lasciato uno spartito disegnato. Io leggo solo spartiti al burro.»';choice('Dove trovo la melodia?',()=>say('«Guarda lo spartito in piazza. Poi usa l’organetto al molo. I simboli vanno da sinistra a destra.»',p.name,p.char));choice('E se suonassi il mattarello?',()=>say('«Solo se il concerto finisce con una torta.»',p.name,p.char));}
  else if(c===2){greeting='«La serratura vuole il colore di un’arancia. Ho messo una vera arancia nella serratura. Adesso vuole anche un tovagliolo.»';choice('Come si mescolano i colori?',()=>say('«Prendi le bottiglie. Scegli un colore nelle tasche e poi un altro: Pippo li mescola. Se sbagli puoi provare ancora!»','Ada',2));choice('Un gelato blu sa di mare?',()=>say('«Solo se lo mangi facendo SPLASH. Ti sconsiglio l’esperimento.»','Ada',2));}
  else if(c===3&&p.id==='baron'){greeting='Tre attori: «Uno di noi ha preso la corona… gli altri due hanno preso soltanto l’applauso!»';choice('Confrontiamo i sospettati',()=>showPuzzle('suspect'));choice('Una corona rende bravi a comandare?',()=>say('«No, ma tiene fermi i capelli durante i discorsi lunghi.»','Le tre maschere',3));}
  else if(c===3){greeting='«Ho trovato stivali sporchi. O forse hanno trovato me. Guarda le impronte per capire chi è passato!»';choice('Come riconosco il colpevole?',()=>say('«Ti servono due indizi: gli stivali e il colore dei guanti. Un solo indizio potrebbe indicare due persone diverse.»','Berto',1));choice('Anche il fango può testimoniare?',()=>say('«Certo. Ma lascia tutte le sue dichiarazioni sul pavimento.»','Berto',1));}
  else if(c===4){greeting=p.id==='baron'?'«Ho migliorato la macchina! Adesso sbaglia tutti i pacchi, ma con grande precisione.»':'«Aspettavo farina, è arrivato un cappello. La torta è diventata elegante ma immangiabile.»';choice('Qual è l’ordine dei pacchi?',()=>say('«Il cartello al festival mostra come metterli in fila. Guarda il disegno e poi usa la macchina del magazzino.»',p.name,p.char));choice('Posso spedire il Barone sulla Luna?',()=>say('«Prima dovresti trovare una busta abbastanza grande. Meglio risolvere questo pasticcio!»',p.name,p.char));}
  else if(p.id==='baron'){greeting='«Ho preso le ciambelle, i campanelli e la corona! Ora mi prenderò il titolo di persona più importante del porto!»';choice('Importante è chi aiuta, non chi prende.',()=>say('«Ma… nessuno mi aveva invitato alla festa.» Pippo: «Riporta tutto e aiuta a sistemare il porto. Poi ne parliamo davanti a una ciambella.»','Barone Sottosopra',3));choice('Il tuo cappello sa spostare le nuvole?',()=>say('«No. Ho provato. Adesso piove dentro il cappello.»','Barone Sottosopra',3));}
  else{greeting='«Al magazzino c’è un telo leggero. Al faro trovi una corda. Mi sembra l’inizio di un’idea che vola!»';choice('Posso costruire qualcosa?',()=>say('«Prendi il telo e la corda. Per combinarli, scegli prima uno e poi l’altro nelle tasche. Il vento farà il resto.»','Berto',1));choice('La nuvola si può mettere in tasca?',()=>say('«Sì, ma ti ritroveresti i pantaloni pieni di pioggia.»','Berto',1));}
  say(greeting,p.name,p.char,choices);
 }
 function renderInventory(){const bag=$('inventory');bag.replaceChildren();if(!state.inventory.length){const empty=document.createElement('span');I.text(empty,'Solo briciole. Per ora.');bag.append(empty);}state.inventory.forEach(id=>{const b=document.createElement('button');b.innerHTML=icon(E.items[id][1]);const label=document.createElement('span');I.text(label,E.items[id][0]);b.append(label);b.classList.toggle('selected',selected===id);b.setAttribute('aria-pressed',String(selected===id));b.onclick=()=>{if(selected&&selected!==id){const first=selected;selected=null;handleResult(E.combine(state,first,id));return;}selected=selected===id?null:id;setVerb('use');renderInventory();I.text($('actionText'),selected?'Usa '+E.items[selected][0]+' con…':'Usa…');say(selected?`${E.items[id][0]} selezionato. Tocca un altro oggetto nelle tasche per combinarli, oppure un oggetto nella scena per usarlo.`:'Oggetto rimesso in tasca.');};bag.append(b);});}
 function render(){const c=E.cases[state.caseIndex],done=state.completed.includes(state.caseIndex);I.text($('rank'),E.ranks[state.completed.length]);I.text($('stars'),I.format('stars',state.stars));I.text($('chapter'),I.format('chapter',state.caseIndex+1));I.text($('caseTitle'),c.title);I.text($('location'),E.places[state.room]);I.text($('voice'),state.voice?'Voce: sì':'Voce: no');$('scene').className='scene scene-'+state.room;renderVehicle();$('pippo').classList.add('pippo-sprite','idle');I.text($('saveStatus'),saveAvailable?'I tuoi progressi si salvano da soli.':'Salvataggio non disponibile: tieni aperta questa pagina.');
  $('hotspots').replaceChildren();E.props[state.caseIndex].filter(p=>p.room===state.room&&(!p.item||!state.inventory.includes(p.item))&&!(state.inventory.includes('kite')&&['cloth','rope'].includes(p.item))).forEach(p=>{const b=document.createElement('button');b.className='hotspot '+(p.char!==undefined?'person':'prop');b.style.left=p.x+'%';b.style.bottom=p.y+'%';b.dataset.id=p.id;I.attribute(b,'aria-label',p.name);if(p.char!==undefined){const char=document.createElement('div');char.className='character char-'+p.char;b.append(char);}else b.innerHTML=icon(p.icon);const caption=document.createElement('span');caption.className='caption';I.text(caption,p.name);b.append(caption);b.onclick=event=>{event.stopPropagation();interact(p);};b.onmouseenter=()=>{I.text($('actionText'),({look:'Guarda ',talk:'Parla con ',take:'Prendi ',use:selected?`Usa ${E.items[selected][0]} con `:'Usa '})[verb]+p.name);};$('hotspots').append(b);});
  $('travel').replaceChildren();c.rooms.filter(room=>room!==state.room).forEach(room=>{const b=document.createElement('button');I.text(b,'↪ '+E.places[room]);b.dataset.room=String(room);b.onclick=event=>{event.stopPropagation();goToRoom(room);};$('travel').append(b);});renderInventory();$('next').hidden=!done||state.caseIndex===5;I.text($('next'),state.vehicle>state.caseIndex&&state.station>state.caseIndex?'Il prossimo mistero →':'Prepara il prossimo caso →');renderHub();}
 function showHub(promotion=false){$('adventure').hidden=true;$('hub').hidden=false;renderHub();if(promotion)I.text($('hubMessage'),state.completed.length===6?'Sei l’Eroe di Porto Buffo. Tutti i misteri del Barone sono risolti!':'Promozione ottenuta! Sblocca il prossimo mezzo e il prossimo reparto: 2 stelle ciascuno.');}

 let tripTimer=null,activeDepartment=0,labSelection=[];
 function showAdventure(){if($('stationDialog').open)$('stationDialog').close();$('hub').hidden=true;$('adventure').hidden=false;render();}
 function renderVehicle(){const i=state.activeVehicle??state.vehicle;$('parkedVehicle').innerHTML=V.svg(i);const caption=document.createElement('span');I.text(caption,E.vehicles[i]);$('parkedVehicle').append(caption);I.attribute($('parkedVehicle'),'aria-label',V.info[i][0]);}
 function animateVehicle(){const i=state.activeVehicle??state.vehicle,trip=$('trip');clearTimeout(tripTimer);trip.hidden=false;trip.className=i===5?'flight':i===3?'sprint':'';trip.innerHTML=V.svg(i);trip.style.animation='none';void trip.offsetWidth;trip.style.animation='';tripTimer=setTimeout(()=>trip.hidden=true,1000);}
 function goToRoom(room){if(!E.travel(state,room)){say('Per raggiungere il faro serve l’Elicottero. Selezionalo nel garage.');return false;}selected=null;persist();animateVehicle();say('Con '+E.vehicles[state.activeVehicle]+' raggiungo '+E.places[room]+'.');return true;}
 function renderHub(){for(const [target,kind,list]of[['vehicles','vehicle',E.vehicles],['stations','station',E.stations]]){$(target).replaceChildren();list.forEach((title,i)=>{const card=document.createElement('article');card.className='card'+(i===(kind==='vehicle'?state.activeVehicle:state.station)?' owned':'');const number=document.createElement('span');number.className='number';I.text(number,String(i+1).padStart(2,'0'));const h=document.createElement('h3');I.text(h,title);const p=document.createElement('p');I.text(p,kind==='vehicle'?V.info[i][1]:E.cases[i].type);const button=document.createElement('button');const owned=i<=state[kind];I.text(button,owned?(kind==='vehicle'?(i===state.activeVehicle?'✓ In uso':'Usa '+title):'Apri reparto'):state.completed.length<i?I.format('locked',i):'Sblocca · 2 stelle');button.disabled=!owned&&(i!==state[kind]+1||state.completed.length<i||state.stars<2);button.onclick=()=>{if(owned){if(kind==='vehicle'){E.selectVehicle(state,i);persist();I.text($('hubMessage'),title+' pronto! Toccalo nella scena per usarlo.');}else openDepartment(i);}else if(E.purchase(state,kind,i)){persist();I.text($('hubMessage'),title+' sbloccato!');}};card.append(number,h);if(kind==='vehicle'){const art=document.createElement('div');art.className='vehicle-art';art.innerHTML=V.svg(i);card.append(art);}else{const art=document.createElement('div');art.className='station-art station-art-'+i;art.setAttribute('aria-hidden','true');card.append(art);}card.append(p,button);$(target).append(card);});}$('caseCards').replaceChildren();E.cases.forEach((c,i)=>{const article=document.createElement('article');article.className='case-entry';const h=document.createElement('h3');I.text(h,(state.completed.includes(i)?'✓ ':i===state.caseIndex?'◆ ':'◇ ')+c.title);const p=document.createElement('p');I.text(p,c.type);article.append(h,p);$('caseCards').append(article);});I.text($('hubMessage'),'Scegli un mezzo acquistato o apri un reparto. Ogni nuovo mezzo e reparto costa 2 stelle.');}
 function departmentButton(label,action,disabled=false){const b=document.createElement('button');if(label)I.text(b,label);b.disabled=disabled;b.onclick=action;$('stationControls').append(b);return b;}
 function departmentAction(action,value){const result=E.stationAction(state,activeDepartment,action,value);persist();renderDepartment();I.text($('stationFeedback'),result.text);speak(result.text);if(result.notes){I.text($('stationVisual'),result.notes.map(x=>symbols[x]).join(' → '));result.notes.forEach((key,i)=>setTimeout(()=>tone(key),i*600));}if(result.done)handleResult(result);}
 function openDepartment(index){activeDepartment=index;labSelection=[];renderDepartment();I.text($('stationFeedback'),'');$('stationDialog').showModal();}
 function renderDepartment(){const i=activeDepartment;I.text($('stationTitle'),E.stations[i]);$('stationControls').replaceChildren();I.clearText($('stationVisual'));I.text($('stationDescription'),['Leggi il fascicolo e scegli dove partire.','Ascolta lo spartito trovato in piazza.','Scegli due bottiglie raccolte durante il caso.','Confronta le schede con entrambi gli indizi raccolti.','Metti i pacchi in ordine e caricali sul camion.','Costruisci l’aquilone, consulta il radar e vola al faro.'][i]);
  if(i===0){departmentButton('Leggi il fascicolo',()=>departmentAction('brief'));departmentButton('Apri il diario',()=>{$('stationDialog').close();showJournal();});}
  if(i===1)departmentButton('Riproduci melodia',()=>departmentAction('listen'));
  if(i===2){$('stationVisual').innerHTML=state.inventory.filter(x=>['orange','purple','green'].includes(x)).map(icon).join('');for(const colour of ['red','yellow','blue']){const b=departmentButton('',()=>{labSelection.push(colour);if(labSelection.length===2){const pair=labSelection;labSelection=[];departmentAction('mix',pair);}else{renderDepartment();I.text($('stationFeedback'),'Ora scegli il secondo colore.');}},!state.inventory.includes(colour)||labSelection.includes(colour));b.innerHTML=icon(colour);const caption=document.createElement('span');I.text(caption,E.items[colour][0]);b.append(caption);b.classList.toggle('selected',labSelection.includes(colour));}}
  if(i===3){I.text($('stationVisual'),'Guanti: '+(state.flags.includes('gloves')?'rossi':'indizio da cercare')+' · Stivali: '+(state.flags.includes('boots')?'infangati':'indizio da cercare'));for(const [id,name]of [['wizard','Mago: blu / sporchi'],['jester','Giullare: rossi / puliti'],['pirate','Pirata: rossi / sporchi']])departmentButton(name,()=>departmentAction('compare',id));}
  if(i===4){$('stationVisual').innerHTML=state.parcels.map(size=>icon('parcel'+size)).join('');state.parcels.forEach((size,index)=>departmentButton(['','Piccolo','Medio','Grande'][size]+' ←',()=>departmentAction('move',index),index===0||state.caseIndex!==4));departmentButton('Carica e consegna',()=>departmentAction('deliver'));}
  if(i===5){$('stationVisual').innerHTML=icon(state.inventory.includes('kite')?'kite':'cloudMachine');departmentButton('Costruisci aquilone',()=>departmentAction('build'),state.inventory.includes('kite'));departmentButton('Consulta radar',()=>departmentAction('survey'));}
  for(const room of E.cases[state.caseIndex].rooms)departmentButton('Parti: '+E.places[room],()=>{showAdventure();goToRoom(room);});
 }
 $('closeStation').onclick=()=>$('stationDialog').close();
 $('parkedVehicle').onclick=event=>{event.stopPropagation();const i=state.activeVehicle??state.vehicle;if(i===0){tone('star');say('DRIN DRIN! Pippo arriva in bicicletta. Tutti possono attraversare in sicurezza.');}else if(i===1){$('scene').classList.toggle('headlight');say('Faro della moto acceso! Ora controllo meglio gli angoli in ombra.');}else if(i===2){$('scene').classList.add('vehicle-flash');tone('sun');setTimeout(()=>tone('moon'),250);setTimeout(()=>$('scene').classList.remove('vehicle-flash'),2000);say('Nino-nino! La pattuglia avvisa il porto: Pippo è in servizio.');}else if(i===3){animateVehicle();say('Partenza sprint! Rapido come una ciambella che rotola.');}else {showHub();openDepartment(i);}};
 const puzzleData={
  riddle:{type:'UN INDOVINELLO DI BERTO',title:'Ho i denti, ma non mangio…',prompt:'Ho i denti, ma non mangio. Apro le porte, ma non cammino. Chi sono?',options:[['comb','Pettine','comb'],['key','Chiave','key'],['fork','Forchetta','fork']]},
  melody:{type:'LA MELODIA DEL NASCONDIGLIO',title:'Tre tasti, quattro note',prompt:'Suona i simboli nell’ordine dello spartito. Non serve fare in fretta!',options:[['sun','Sole','sun'],['moon','Luna','moon'],['star','Stella','star']]},
  suspect:{type:'PICCOLI DETECTIVE',title:'Chi ha preso la corona?',prompt:'Confronta guanti e stivali. Il sospettato deve corrispondere a ENTRAMBI gli indizi.',options:[['wizard','Mago: guanti blu, stivali sporchi','blue'],['jester','Giullare: guanti rossi, stivali puliti','red'],['pirate','Pirata: guanti rossi, stivali sporchi','redCloth']]},
  parcels:{type:'LA MACCHINA SOTTO SOPRA',title:'Un posto per ogni pacco',prompt:'Tocca un pacco per spostarlo di un posto a sinistra. Quando sono in ordine, premi Consegna.'},
  windRiddle:{type:'L’ULTIMO INDOVINELLO',title:'Volo, ma non ho un motore…',prompt:'Volo con il vento, non ho un motore. Un filo mi tiene vicino al mio inventore. Chi sono?',options:[['boat','Barca','boat'],['helicopter','Elicottero','helicopter'],['kite','Aquilone','kite']]},
  wind:{type:'LIBERIAMO IL FARO',title:'Dove portiamo la nuvola?',prompt:'La nuvola deve andare dove non nasconde il faro e non disturba le barche. Scegli un posto libero.',options:[['port','Porto delle barche','boat'],['sea','Mare aperto','sea'],['lighthouse','Sopra il faro','lighthouse']]}
 };
 function renderPuzzle(){const d=puzzleData[activePuzzle];I.text($('puzzleType'),d.type);I.text($('puzzleTitle'),d.title);I.text($('puzzlePrompt'),d.prompt);$('puzzleOptions').replaceChildren();let clue='';
  if(activePuzzle==='melody')clue=(state.flags.includes('score')?'Spartito: Sole → Luna → Sole → Stella. ':'Non hai ancora trovato lo spartito in piazza. ')+`Note suonate: ${state.sequence.map(x=>symbols[x]).join(' · ')||'nessuna'}`;
  if(activePuzzle==='suspect')clue=`Stoffa: ${state.flags.includes('gloves')?'guanto rosso':'da cercare nel teatro'}. Impronte: ${state.flags.includes('boots')?'stivali infangati':'da cercare al molo'}.`;
  if(activePuzzle==='parcels')clue=state.flags.includes('sizes')?'Cartello: piccolo → medio → grande.':'Il cartello al festival spiega l’ordine dei pacchi.';
  if(I.settings.difficulty==='challenge')clue='';if(I.settings.difficulty==='easy')clue+=' '+E.hintFor(state,'easy');I.text($('puzzleClue'),clue);
  const options=activePuzzle==='parcels'?state.parcels.map((size,index)=>[index,['','Piccolo','Medio','Grande'][size]+' ←','parcel'+size]):d.options;
  options.forEach(([value,label,image],i)=>{const b=document.createElement('button');b.innerHTML=icon(image);const text=document.createElement('span');I.text(text,label);b.append(text);if(activePuzzle==='parcels'&&i===0)b.disabled=true;b.onclick=()=>submitPuzzle(value);$('puzzleOptions').append(b);});
  if(activePuzzle==='parcels'){const b=document.createElement('button');I.text(b,'Consegna →');b.onclick=()=>submitPuzzle('confirm');$('puzzleOptions').append(b);}
  if(activePuzzle==='melody'){const b=document.createElement('button');I.text(b,'Ricomincia melodia');b.onclick=()=>{state.sequence=[];persist();renderPuzzle();I.text($('puzzleFeedback'),'Ripartiamo dalla prima nota.');};$('puzzleOptions').append(b);}
 }
 function showPuzzle(kind,feedback=""){activePuzzle=kind;renderPuzzle();I.text($('puzzleFeedback'),'');if(!$('puzzleDialog').open)$('puzzleDialog').showModal();speak(feedback+' '+$('puzzlePrompt').textContent+' '+$('puzzleClue').textContent);}
 function submitPuzzle(value){const before=activePuzzle;if(before==='melody')tone(value);const result=E.answer(state,before,value,I.settings.difficulty);persist();if(result.done){activePuzzle=null;handleResult(result);return;}if(result.puzzle){showPuzzle(result.puzzle,I.t(result.text));I.text($('puzzleFeedback'),result.text);return;}renderPuzzle();I.text($('puzzleFeedback'),result.text);if(before!=='melody')speak(result.text);if(before==='riddle'&&result.ok){$('puzzleDialog').close();activePuzzle=null;say(result.text,'Berto',1);}}
 function showJournal(){const c=E.cases[state.caseIndex];I.text($('journalTitle'),c.title);I.text($('journalBrief'),c.brief);$('journalNotes').replaceChildren();const notes=[c.goal];const meanings={riddle:'Berto ha dato la chiave del baule.',score:'Spartito: Sole → Luna → Sole → Stella.',gloves:'Indizio 1: il colpevole ha guanti rossi.',boots:'Indizio 2: il colpevole ha stivali infangati.',sizes:'Ordine dei pacchi: piccolo → medio → grande.',windRiddle:'Il vento cerca un aquilone.',done:'Caso risolto! 5 stelle guadagnate.'};state.flags.forEach(flag=>notes.push(meanings[flag]));state.inventory.forEach(item=>notes.push('Nelle tasche: '+E.items[item][0]));notes.forEach((text,i)=>{const note=document.createElement('div');note.className='note';const mark=document.createElement('b');I.text(mark,i===0?'◆':'•');const body=document.createElement('span');I.text(body,text);note.append(mark,body);$('journalNotes').append(note);});$('journal').showModal();speak(c.goal);}
 document.querySelectorAll('[data-verb]').forEach(b=>b.onclick=()=>setVerb(b.dataset.verb));$('scene').onclick=event=>{const rect=$('scene').getBoundingClientRect();walk((event.clientX-rect.left)/rect.width*100);};$('voice').onclick=()=>{state.voice=!state.voice;if(!state.voice&&'speechSynthesis'in window)window.PippoSpeech.stop();persist();};$('read').onclick=()=>speak($('message').textContent,$('speaker').textContent,true);$('readPuzzle').onclick=()=>speak($('puzzlePrompt').textContent+' '+$('puzzleClue').textContent,'Pippo',true);$('closePuzzle').onclick=()=>{$('puzzleDialog').close();activePuzzle=null;};$('closeJournal').onclick=()=>$('journal').close();$('journalButton').onclick=showJournal;$('hubButton').onclick=()=>showHub();$('back').onclick=()=>{$('hub').hidden=true;$('adventure').hidden=false;render();};$('help').onclick=()=>{const hints=E.cases[state.caseIndex].hints;say(E.hintFor(state,I.settings.difficulty),'Il diario di Pippo');state.hintLevel=Math.min(3,state.hintLevel+1);persist();};$('next').onclick=()=>{if(E.advance(state)){selected=null;setVerb('look');persist();animateVehicle();say(E.cases[state.caseIndex].intro+' '+E.cases[state.caseIndex].brief);}else showHub(true);};$('reset').onclick=()=>$('resetDialog').showModal();$('cancelReset').onclick=()=>$('resetDialog').close();$('confirmReset').onclick=()=>{state=E.initialState();selected=null;verb='look';activePuzzle=null;$('resetDialog').close();$('hub').hidden=true;$('adventure').hidden=false;setVerb('look');persist();say(E.cases[0].intro+' '+E.cases[0].brief);};render();setVerb('look');I.text($('message'),state.completed.includes(state.caseIndex)?'I tuoi progressi precedenti sono conservati. Puoi continuare, oppure scegliere Nuova partita per giocare tutti i nuovi enigmi.':E.cases[state.caseIndex].intro+' '+E.cases[state.caseIndex].brief);
window.PippoGame={save:persist,getState:()=>state,setVoice:value=>{state.voice=value;if(!value&&'speechSynthesis'in window)window.PippoSpeech.stop();persist();},stopSounds:()=>{if(audioContext)audioContext.suspend();},resetHints:()=>{state.hintLevel=0;persist();if(activePuzzle)renderPuzzle();}};
})();
